<?= $this->extend('layouts/app') ?><?= $this->section('content') ?>
<?php $role=(string)session()->get('role'); $canSubmit=in_array($role,['manager','facilitator'],true); ?>
<div class="page-head"><div><h1><?= esc($title) ?></h1><p><?= $resultType==='match'?'Enter live match scores. Results remain unofficial until validator acceptance.':'Enter judged scores; placements are calculated from the submitted scores and become official only after validation.' ?></p></div><?php if($canSubmit): ?><button class="btn primary" data-modal="result-modal">+ Encode Result</button><?php endif; ?></div>
<section class="panel"><div class="panel-head"><div><h2><?= $resultType==='match'?'Match Bracket':'Judged Event Bracket' ?></h2><p>Schedules are grouped by round and horizontally scrollable.</p></div></div><?php $bracket=[]; foreach($schedules as $bs){$bracket[$bs['round']][]=$bs;} ?><div class="bracket-board"><?php foreach($bracket as $round=>$roundSchedules): ?><div class="bracket-stage"><h3><?= esc($round) ?></h3><?php foreach($roundSchedules as $bs): ?><article class="bracket-match"><b><?= esc($bs['sport_name'].' · '.$bs['category']) ?></b><span><?= $resultType==='match'?esc(($bs['team_a_name']??'Open').' vs '.($bs['team_b_name']??'Open')):'All participating teams' ?></span><small><?= esc(($bs['location_name']??'—').' · '.date('M j, g:i A',strtotime($bs['match_date']))) ?></small><em><?= strtoupper(esc($bs['status'])) ?></em></article><?php endforeach; ?></div><?php endforeach; ?></div></section>
<section class="panel"><div class="panel-head"><div><h2><?= $resultType==='match'?'Match Schedules':'Judged Schedules' ?></h2><p>Detailed active event schedule list</p></div></div><div class="table-wrap"><table><thead><tr><th>Sport</th><th>Round</th><th>Location</th><th>Teams</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($schedules as $s): ?><tr><td><b><?= esc($s['sport_name']) ?></b><small class="muted"><?= esc($s['category']) ?></small></td><td><?= esc($s['round']) ?></td><td><?= esc($s['location_name']??'—') ?></td><td><?= $resultType==='match'?esc(($s['team_a_name']??'Open').' vs '.($s['team_b_name']??'Open')):'All participating teams' ?></td><td><?= esc(date('M j, g:i A',strtotime($s['match_date']))) ?></td><td><span class="badge neutral"><?= strtoupper(esc($s['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2><?= esc($title) ?></h2><p>Official and unofficial results are clearly separated by status.</p></div></div><div class="result-list"><?php if(!$results): ?><div class="empty">No results have been submitted yet.</div><?php endif; ?><?php foreach($results as $r): ?><article class="result-card"><div class="result-top"><div><b><?= esc($r['sport_name'].' · '.$r['category']) ?></b><span><?= esc($r['round']) ?> · <?= esc($r['location_name']??'') ?></span></div><span class="badge <?= $r['status']==='validated'?'official':'unofficial' ?>"><?= $r['status']==='validated'?'OFFICIAL':'UNOFFICIAL' ?></span></div><div class="score-entries"><?php foreach($r['entries'] as $e): ?><div><span><?= esc($e['team_name']) ?></span><strong><?= number_format((float)$e['raw_score'],2) ?></strong><?php if($e['placement']): ?><small>#<?= (int)$e['placement'] ?> · <?= number_format((float)$e['allocated_points'],0) ?> pts</small><?php endif; ?></div><?php endforeach; ?></div><div class="result-foot"><small>Submitted by <?= esc($r['submitted_by_name']??'System') ?> · <?= esc(date('M j, g:i A',strtotime($r['submitted_at']))) ?></small><?php if($role==='validator'&&$r['status']==='pending'): ?><form method="post" action="<?= site_url('results/'.$r['id'].'/validate') ?>" class="validate-form"><?= csrf_field() ?><label class="check compact-check"><input type="checkbox" name="confirmed_sheet" value="1" required> Compared with official score sheet/form</label><button class="btn tiny primary">Validate as Official</button></form><?php elseif($r['status']==='validated'): ?><small>Validated by <?= esc($r['validated_by_name']??'Validator') ?></small><?php endif; ?></div></article><?php endforeach; ?></div></section>
<?php if($canSubmit): ?><dialog id="result-modal"><form method="post" action="<?= site_url('results') ?>" class="modal-card wide" id="result-form"><?= csrf_field() ?><div class="modal-head"><h2>Encode <?= $resultType==='match'?'Match':'Judged' ?> Result</h2><button type="button" data-close>×</button></div><label>Schedule<select name="schedule_id" required><option value="">Select schedule</option><?php foreach($schedules as $s): ?><option value="<?= $s['id'] ?>" data-team-a="<?= esc($s['team_a_name']??'Team A') ?>" data-team-b="<?= esc($s['team_b_name']??'Team B') ?>"><?= esc($s['sport_name'].' · '.$s['round'].' · '.date('M j g:i A',strtotime($s['match_date']))) ?></option><?php endforeach; ?></select></label><?php if($resultType==='match'): ?><div class="form-grid"><label>Team A Score<input type="number" step="0.01" min="0" name="team_a_score" required></label><label>Team B Score<input type="number" step="0.01" min="0" name="team_b_score" required></label></div><?php else: ?><div class="judged-grid"><?php foreach($teams as $t): ?><label><?= esc($t['name']) ?><input type="number" step="0.01" min="0" name="judged[<?= $t['id'] ?>]" placeholder="Score"></label><?php endforeach; ?></div><?php endif; ?><label>Notes<textarea name="notes" rows="3" placeholder="Optional notes from the score sheet"></textarea></label><div class="warning-box">This submission is published immediately as <b>UNOFFICIAL</b>. A designated validator must compare it with the actual score sheet/form before it becomes official.</div><button class="btn primary full">Submit Unofficial Result</button></form></dialog><?php endif; ?>
<?= $this->endSection() ?>
